using Creator = std::function<std::unique_ptr<Payment>()>;
class PaymentRegistry {
public:
    static std::unique_ptr<Payment> create(const std::string& kind) {
        return creators().at(kind)();        // throws on unknown kind
    }
private:
    static std::unordered_map<std::string, Creator>& creators() {
        static std::unordered_map<std::string, Creator> map;   // Meyers singleton
        return map;
    }
};

struct OrderFactory {
    virtual ~OrderFactory() = default;
    virtual std::unique_ptr<Order> from_cart(const RawOrder&) const = 0;
};
class RetailOrderFactory final : public OrderFactory {
public:
    std::unique_ptr<Order> from_cart(const RawOrder& raw) const override {
        return std::make_unique<Order>(OrderId::create(), raw.customer_id);
    }
};
